/* Claude Certification Hub – mock exam engine.
 * Runs entirely in the browser. Nothing is stored or sent anywhere.
 * Data: docs/assets/data/qbank.json or qbank-dev.json (generated by tools/qbank/build*.py)
 * Supports single-answer and multiple-response ("Select TWO") questions.
 */
(function () {
  "use strict";
  var LETTERS = ["A", "B", "C", "D", "E", "F"];
  var SCEN_ORDER = ["S1", "S2", "S3", "S4", "S5", "S6", "G"];

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = text;
    return e;
  }
  function btn(label, cls, onClick) {
    var b = el("button", "md-button " + (cls || ""), label);
    b.type = "button";
    b.addEventListener("click", onClick);
    return b;
  }
  function fmtTime(s) {
    s = Math.max(0, s);
    var m = Math.floor(s / 60), r = s % 60;
    return (m < 10 ? "0" : "") + m + ":" + (r < 10 ? "0" : "") + r;
  }

  function scrollTo(node) {
    var header = document.querySelector(".md-header");
    var offset = (header ? header.offsetHeight : 0) + 16;
    var top = node.getBoundingClientRect().top + window.pageYOffset - offset;
    if (Math.abs(window.pageYOffset - top) > 4) window.scrollTo(0, top);
  }

  function init(root) {
    if (root.dataset.ready) return;
    root.dataset.ready = "1";
    fetch(root.getAttribute("data-src"))
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (data) { new Exam(root, data).home(); })
      .catch(function () {
        root.innerHTML = "";
        root.appendChild(el("p", "hub-mock-error",
          "Sorry, the question data couldn't be loaded. Please use the question bank pages instead."));
      });
  }

  /* ---------- answer helpers (single = index, multiple-response = sorted list) ---------- */
  function isMulti(q) { return Array.isArray(q.answers); }
  function hasAnswer(a) { return a !== undefined && (!Array.isArray(a) || a.length > 0); }
  function isPicked(a, i) { return Array.isArray(a) ? a.indexOf(i) !== -1 : a === i; }
  function isKey(q, i) { return isMulti(q) ? q.answers.indexOf(i) !== -1 : q.answer === i; }
  function isCorrect(q, a) {
    if (!isMulti(q)) return a === q.answer;
    if (!Array.isArray(a) || a.length !== q.answers.length) return false;
    return q.answers.every(function (k) { return a.indexOf(k) !== -1; });
  }
  function countAnswered(st) {
    return st.qs.filter(function (q) { return hasAnswer(st.answers[q.id]); }).length;
  }

  function Exam(root, data) {
    this.root = root; this.data = data; this.timer = null;
    this.mocks = data.mocks || ["A", "B", "C"];
    this.minutes = data.minutes || 120;
    this.scenarios = data.scenarios || {};
    this.beforeUnload = function (e) { e.preventDefault(); e.returnValue = ""; };
  }

  Exam.prototype.clear = function () { this.root.innerHTML = ""; };

  /* ---------- Start screen ---------- */
  Exam.prototype.home = function () {
    var self = this; this.stopTimer(); this.clear();
    var wrap = el("div", "hub-mock-home");
    wrap.appendChild(el("h2", null, "Choose a mock exam"));
    var grid = el("div", "hub-mock-choices");
    this.mocks.forEach(function (m) {
      var n = self.data.questions.filter(function (q) { return q.mock === m; }).length;
      var card = el("div", "hub-mock-choice");
      card.appendChild(el("h3", null, "Mock exam " + m));
      card.appendChild(el("p", null, n + " questions · " + (self.data.blurb || "weighted by domain · grouped by scenario")));
      card.appendChild(btn("Start mock " + m, "md-button--primary", function () { self.start(m); }));
      grid.appendChild(card);
    });
    wrap.appendChild(grid);
    if (this.data.sim) {
      var sim = this.data.sim, simCard = el("div", "hub-mock-choice hub-mock-choice--sim");
      simCard.appendChild(el("h3", null, "Exam simulation"));
      simCard.appendChild(el("p", null, sim.type === "scenarios"
        ? "A new paper every time: " + sim.pick + " scenarios chosen at random from " + (Object.keys(this.data.scenarioIntro || {}).length || 6) +
          ", " + sim.per + " questions each, like the published exam structure. Drawn from the whole bank, so you will meet questions from the fixed mocks again."
        : "A new paper every time: questions drawn at random from the whole bank in the published domain proportions. You will meet questions from the fixed mocks again."));
      simCard.appendChild(btn("Start a simulation", "md-button--primary", function () { self.startSim(); }));
      wrap.appendChild(simCard);
    }
    var opts = el("label", "hub-mock-timer-opt");
    var cb = el("input"); cb.type = "checkbox"; cb.checked = true; cb.id = "hub-mock-timed";
    opts.appendChild(cb);
    opts.appendChild(document.createTextNode(" Use the " + this.minutes + "-minute timer (recommended for exam practice)"));
    wrap.appendChild(opts);
    this.root.appendChild(wrap);
  };

  /* ---------- Exam ---------- */
  Exam.prototype.start = function (mock) {
    var qs = this.data.questions.filter(function (q) { return q.mock === mock; });
    qs.sort(function (a, b) {
      if (a.order !== undefined && b.order !== undefined) return a.order - b.order;
      var s = SCEN_ORDER.indexOf(a.scenario) - SCEN_ORDER.indexOf(b.scenario);
      return s !== 0 ? s : (a.id < b.id ? -1 : 1);
    });
    this.begin(mock, "Mock " + mock, qs);
  };

  function shuffle(a) {
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1)), t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  /* Exam simulation: a fresh random paper drawn from the whole bank. */
  Exam.prototype.startSim = function () {
    var sim = this.data.sim, all = this.data.questions, qs = [];
    if (sim.type === "scenarios") {
      var names = shuffle(Object.keys(this.data.scenarioIntro || {})).slice(0, sim.pick);
      var filler = shuffle(all.filter(function (q) { return q.scenario === sim.filler; }));
      names.forEach(function (sc) {
        var pool = shuffle(all.filter(function (q) { return q.scenario === sc; })).slice(0, sim.per);
        while (pool.length < sim.per && filler.length) {            // top up thin scenarios with general questions
          var f = filler.pop(), copy = {}; for (var k in f) copy[k] = f[k];
          copy.scenario = sc; pool.push(copy);
        }
        qs = qs.concat(pool);
      });
    } else {
      Object.keys(sim.counts).forEach(function (d) {
        qs = qs.concat(shuffle(all.filter(function (q) { return q.domain === d; })).slice(0, sim.counts[d]));
      });
      shuffle(qs);
    }
    this.begin("sim", "Exam simulation", qs);
  };

  Exam.prototype.begin = function (mock, label, qs) {
    var timedEl = document.getElementById("hub-mock-timed");
    // scenario groups, for "Scenario 2 of 4" headers
    var groups = [], seen = {};
    var intros = this.data.scenarioIntro || {};
    qs.forEach(function (q) { if (intros[q.scenario] && !seen[q.scenario]) { seen[q.scenario] = 1; groups.push(q.scenario); } });
    this.state = { mock: mock, label: label, groups: groups, qs: qs, idx: 0, answers: {}, flags: {},
                   timed: timedEl ? timedEl.checked : true, remaining: this.minutes * 60 };
    window.addEventListener("beforeunload", this.beforeUnload);
    if (this.state.timed) this.startTimer();
    this.renderQuestion();
  };

  Exam.prototype.startTimer = function () {
    var self = this; this.stopTimer();
    this.timer = setInterval(function () {
      self.state.remaining -= 1;
      var t = self.root.querySelector(".hub-mock-time");
      if (t) {
        t.textContent = fmtTime(self.state.remaining);
        if (self.state.remaining <= 600) t.classList.add("is-low");
      }
      if (self.state.remaining <= 0) { self.finish(true); }
    }, 1000);
  };
  Exam.prototype.stopTimer = function () { if (this.timer) clearInterval(this.timer); this.timer = null; };

  Exam.prototype.renderQuestion = function () {
    var self = this, st = this.state, q = st.qs[st.idx];
    this.clear();
    var shell = el("div", "hub-mock-shell");

    // header
    var head = el("div", "hub-mock-head");
    head.appendChild(el("span", "hub-mock-title", st.label + " · Question " + (st.idx + 1) + " of " + st.qs.length));
    if (st.timed) head.appendChild(el("span", "hub-mock-time" + (st.remaining <= 600 ? " is-low" : ""), fmtTime(st.remaining)));
    shell.appendChild(head);
    var answered = countAnswered(st);
    var bar = el("div", "hub-mock-progress"); var fill = el("div", "hub-mock-progress__fill");
    fill.style.width = (answered / st.qs.length * 100) + "%"; bar.appendChild(fill); shell.appendChild(bar);

    // question
    var card = el("div", "hub-mock-q");
    var multi = isMulti(q), need = multi ? q.answers.length : 1, mine = st.answers[q.id];
    var intro = (this.data.scenarioIntro || {})[q.scenario];
    if (intro) {
      var gi = st.groups.indexOf(q.scenario) + 1;
      var box = el("div", "hub-mock-scenario");
      box.appendChild(el("p", "hub-mock-scen", "Scenario " + gi + " of " + st.groups.length + " · " + this.scenarios[q.scenario]));
      box.appendChild(el("p", "hub-mock-scenario__text", intro));
      card.appendChild(box);
    } else {
      card.appendChild(el("p", "hub-mock-scen", this.scenarios[q.scenario] || (this.data.scenarios ? "General" : this.data.domains[q.domain]) || ""));
    }
    card.appendChild(el("p", "hub-mock-stem", q.stem));
    if (multi) {
      var got = Array.isArray(mine) ? mine.length : 0;
      card.appendChild(el("p", "hub-mock-multi", "Multiple response · select " + need + " · " + got + " of " + need + " chosen"));
      if (st.hint === q.id) card.appendChild(el("p", "hub-mock-multi hub-mock-multi--hint", "You have already chosen " + need + ". Deselect one to change your answer."));
    }
    var list = el("div", "hub-mock-options");
    q.options.forEach(function (text, i) {
      var on = isPicked(mine, i);
      var lab = el("label", "hub-mock-option" + (on ? " is-selected" : "") + (multi ? " is-multi" : ""));
      var r = el("input"); r.type = multi ? "checkbox" : "radio"; r.name = "opt"; r.value = i; r.checked = on;
      r.addEventListener("change", function () {
        if (!multi) { st.answers[q.id] = i; self.renderQuestion(); return; }
        var cur = Array.isArray(st.answers[q.id]) ? st.answers[q.id].slice() : [];
        var at = cur.indexOf(i);
        if (at !== -1) cur.splice(at, 1);
        else if (cur.length >= need) { st.hint = q.id; self.renderQuestion(); return; }   // at the limit: deselect one first
        else cur.push(i);
        st.hint = null;
        cur.sort();
        if (cur.length) st.answers[q.id] = cur; else delete st.answers[q.id];
        self.renderQuestion();
      });
      lab.appendChild(r);
      lab.appendChild(el("span", "hub-mock-letter", LETTERS[i]));
      lab.appendChild(el("span", "hub-mock-text", text));
      list.appendChild(lab);
    });
    card.appendChild(list);
    shell.appendChild(card);

    // controls
    var ctr = el("div", "hub-mock-controls");
    var prev = btn("← Previous", "", function () { st.idx -= 1; self.renderQuestion(); });
    prev.disabled = st.idx === 0; ctr.appendChild(prev);
    ctr.appendChild(btn(st.flags[q.id] ? "★ Flagged" : "☆ Flag for review", "hub-mock-flag" + (st.flags[q.id] ? " is-on" : ""),
      function () { st.flags[q.id] = !st.flags[q.id]; self.renderQuestion(); }));
    if (st.idx < st.qs.length - 1) {
      ctr.appendChild(btn("Next →", "md-button--primary", function () { st.idx += 1; self.renderQuestion(); }));
    } else {
      ctr.appendChild(btn("Review & submit", "md-button--primary", function () { self.confirmSubmit(); }));
    }
    shell.appendChild(ctr);

    // navigator
    var nav = el("div", "hub-mock-nav");
    st.qs.forEach(function (qq, i) {
      var cls = "hub-mock-dot" + (hasAnswer(st.answers[qq.id]) ? " is-answered" : "") +
                (st.flags[qq.id] ? " is-flagged" : "") + (i === st.idx ? " is-current" : "");
      var d = el("button", cls, String(i + 1)); d.type = "button";
      d.setAttribute("aria-label", "Go to question " + (i + 1));
      d.addEventListener("click", function () { st.idx = i; self.renderQuestion(); });
      nav.appendChild(d);
    });
    shell.appendChild(nav);
    var foot = el("div", "hub-mock-foot");
    foot.appendChild(el("span", null, answered + " answered · " + Object.keys(st.flags).filter(function (k) { return st.flags[k]; }).length + " flagged"));
    foot.appendChild(btn("Submit exam", "", function () { self.confirmSubmit(); }));
    shell.appendChild(foot);

    this.root.appendChild(shell);
    scrollTo(shell);
  };

  Exam.prototype.confirmSubmit = function () {
    var self = this, st = this.state;
    var unanswered = st.qs.length - countAnswered(st);
    var partial = st.qs.filter(function (q) {
      var a = st.answers[q.id]; return isMulti(q) && Array.isArray(a) && a.length > 0 && a.length < q.answers.length;
    }).length;
    var flagged = Object.keys(st.flags).filter(function (k) { return st.flags[k]; }).length;
    var box = el("div", "hub-mock-confirm");
    box.appendChild(el("h3", null, "Submit your exam?"));
    box.appendChild(el("p", null, unanswered + " unanswered · " + flagged + " flagged" + (partial ? " · " + partial + " multiple-response question(s) with too few choices" : "") + ". Unanswered questions count as incorrect."));
    var row = el("div", "hub-mock-controls");
    row.appendChild(btn("Keep working", "", function () { self.renderQuestion(); }));
    row.appendChild(btn("Submit now", "md-button--primary", function () { self.finish(false); }));
    box.appendChild(row);
    this.clear(); this.root.appendChild(box);
  };

  /* ---------- Results ---------- */
  Exam.prototype.finish = function (timeUp) {
    var self = this, st = this.state;
    this.stopTimer();
    window.removeEventListener("beforeunload", this.beforeUnload);
    var per = {}, correct = 0;
    Object.keys(this.data.domains).forEach(function (d) { per[d] = { right: 0, total: 0 }; });
    st.qs.forEach(function (q) {
      per[q.domain].total += 1;
      if (isCorrect(q, st.answers[q.id])) { per[q.domain].right += 1; correct += 1; }
    });
    var pct = Math.round(correct / st.qs.length * 100);
    this.clear();
    var res = el("div", "hub-mock-results");
    if (timeUp) res.appendChild(el("p", "hub-mock-timeup", "Time's up! Your exam was submitted automatically."));
    res.appendChild(el("h2", null, st.label + " results"));

    var score = el("div", "hub-mock-score");
    score.appendChild(el("span", "hub-mock-score__pct", pct + "%"));
    score.appendChild(el("span", "hub-mock-score__raw", correct + " of " + st.qs.length + " correct"));
    var band = pct >= 85 ? ["Strong", "Consistently at this level? You're in good shape. Keep reviewing your misses."]
             : pct >= 72 ? ["Getting close", "Focus on your two weakest domains, then try a different mock."]
             : ["Keep building", "Work through the domain pages and labs for your weakest areas before the next attempt."];
    score.appendChild(el("span", "hub-mock-band", band[0]));
    res.appendChild(score);
    res.appendChild(el("p", "hub-mock-band-note", band[1] + " Practice percentages are a guide only, not a predicted exam score."));

    var table = el("div", "hub-mock-domains");
    Object.keys(per).forEach(function (d) {
      var p = per[d]; if (!p.total) return;
      var dp = Math.round(p.right / p.total * 100);
      var row = el("div", "hub-mock-domain");
      row.appendChild(el("span", "hub-mock-domain__name", d + " · " + self.data.domains[d]));
      var b = el("div", "hub-mock-domain__bar"); var f = el("div", "hub-mock-domain__fill" + (dp < 72 ? " is-low" : ""));
      f.style.width = dp + "%"; b.appendChild(f); row.appendChild(b);
      row.appendChild(el("span", "hub-mock-domain__pct", p.right + "/" + p.total + " · " + dp + "%"));
      table.appendChild(row);
    });
    res.appendChild(table);

    var actions = el("div", "hub-mock-controls");
    actions.appendChild(btn("Back to mock list", "", function () { self.home(); }));
    actions.appendChild(st.mock === "sim"
      ? btn("New simulation", "md-button--primary", function () { self.startSim(); })
      : btn("Retake mock " + st.mock, "md-button--primary", function () { self.start(st.mock); }));
    res.appendChild(actions);

    // review
    res.appendChild(el("h2", null, "Review your answers"));
    var filt = el("label", "hub-mock-timer-opt");
    var cb = el("input"); cb.type = "checkbox"; cb.checked = true;
    filt.appendChild(cb); filt.appendChild(document.createTextNode(" Show incorrect and unanswered only"));
    res.appendChild(filt);
    var list = el("div", "hub-mock-review");
    function renderReview() {
      list.innerHTML = "";
      st.qs.forEach(function (q, i) {
        var mine = st.answers[q.id], ok = isCorrect(q, mine);
        if (cb.checked && ok) return;
        var item = el("details", "hub-mock-ritem " + (ok ? "is-right" : "is-wrong"));
        var sum = el("summary");
        sum.appendChild(el("span", "hub-mock-rmark", ok ? "✓" : "✗"));
        sum.appendChild(el("span", null, "Q" + (i + 1) + " · " + q.domain + " · " + q.topic));
        item.appendChild(sum);
        item.appendChild(el("p", "hub-mock-stem", q.stem));
        q.options.forEach(function (text, k) {
          var key = isKey(q, k), picked = isPicked(mine, k);
          var cls = "hub-mock-ropt" + (key ? " is-answer" : "") + (picked && !key ? " is-mine" : "");
          var o = el("div", cls);
          o.appendChild(el("strong", null, LETTERS[k] + ". "));
          o.appendChild(document.createTextNode(text));
          var tag = key ? (picked ? "Correct (you chose this): " : "Correct: ") : (picked ? "Your answer: " : "");
          o.appendChild(el("div", "hub-mock-rnote", tag + q.notes[k]));
          item.appendChild(o);
        });
        if (isMulti(q)) item.insertBefore(el("p", "hub-mock-multi", "Multiple response · all " + q.answers.length + " correct options are needed for the mark"), item.children[2]);
        if (!hasAnswer(mine)) item.appendChild(el("p", "hub-mock-rnote", "You didn't answer this question."));
        list.appendChild(item);
      });
      if (!list.children.length) list.appendChild(el("p", null, "Nothing to review: every answer was correct. 🎉"));
    }
    cb.addEventListener("change", renderReview);
    renderReview();
    res.appendChild(list);
    this.root.appendChild(res);
    scrollTo(res);
  };

  function boot() { var r = document.getElementById("hub-mock"); if (r) init(r); }
  if (typeof document$ !== "undefined") document$.subscribe(boot);
  else document.addEventListener("DOMContentLoaded", boot);
})();
